const SCENE_VIEW_TIMELINE_PLAYER_ID: u64 = u64::MAX;

fn sample_timeline_preview(
    app: &mut engine::App,
    source: &mut Option<(AssetId, TimelineDocument)>,
    request: &TimelinePreviewRequest,
    frame_delta: f32,
) -> TimelinePreviewStatus {
    let requested_state = match request.playback {
        TimelinePreviewPlayback::Stopped => engine::timeline::TimelinePlaybackState::Stopped,
        TimelinePreviewPlayback::Paused => engine::timeline::TimelinePlaybackState::Paused,
        TimelinePreviewPlayback::Playing => engine::timeline::TimelinePlaybackState::Playing,
    };
    let source_changed = source.as_ref().is_none_or(|(asset, document)| {
        asset != &request.asset || document != &request.document
    });
    if source_changed {
        let prepared = match engine::timeline::prepare_timeline_document(
            request.asset.clone(),
            &request.document,
        ) {
            Ok(prepared) => prepared,
            Err(error) => {
                *source = None;
                return TimelinePreviewStatus {
                    tick: request.tick,
                    state: requested_state,
                    diagnostics: vec![error.to_string()],
                };
            }
        };
        app.world_mut()
            .get_resource_mut::<engine::timeline::TimelineRuntime>()
            .expect("Timeline preview registration installs TimelineRuntime")
            .start_with_priority(SCENE_VIEW_TIMELINE_PLAYER_ID, prepared, i32::MAX);
        *source = Some((request.asset.clone(), request.document.clone()));
    }

    let mut control_error = None;
    {
        let runtime = app
            .world_mut()
            .get_resource_mut::<engine::timeline::TimelineRuntime>()
            .expect("Timeline preview registration installs TimelineRuntime");
        if let Err(error) = runtime.set_rate(
            SCENE_VIEW_TIMELINE_PLAYER_ID,
            request.rate_numerator,
            request.rate_denominator,
        ) {
            control_error = Some(error.to_string());
        }
        if control_error.is_none()
            && let Err(error) =
                runtime.set_loop(SCENE_VIEW_TIMELINE_PLAYER_ID, request.loop_range)
        {
            control_error = Some(error.to_string());
        }
        let current_tick = runtime
            .snapshots()
            .into_iter()
            .find(|snapshot| snapshot.player_id == SCENE_VIEW_TIMELINE_PLAYER_ID)
            .map(|snapshot| snapshot.tick)
            .unwrap_or(engine::timeline::TimelineTick::ZERO);
        if control_error.is_none() && current_tick != request.tick
            && let Err(error) = runtime.seek(
                SCENE_VIEW_TIMELINE_PLAYER_ID,
                request.tick,
                request.preview_events,
            )
        {
            control_error = Some(error.to_string());
        }
        if control_error.is_none() {
            let result = match request.playback {
                TimelinePreviewPlayback::Stopped => runtime.stop(SCENE_VIEW_TIMELINE_PLAYER_ID),
                TimelinePreviewPlayback::Paused => runtime.pause(SCENE_VIEW_TIMELINE_PLAYER_ID),
                TimelinePreviewPlayback::Playing => runtime.resume(SCENE_VIEW_TIMELINE_PLAYER_ID),
            };
            if let Err(error) = result {
                control_error = Some(error.to_string());
            }
        }
    }

    run_animation_preview_step(
        app,
        if request.playback == TimelinePreviewPlayback::Playing {
            frame_delta.max(0.0)
        } else {
            0.0
        },
    );

    let runtime = app
        .world()
        .get_resource::<engine::timeline::TimelineRuntime>()
        .expect("Timeline preview registration installs TimelineRuntime");
    let snapshot = runtime
        .snapshots()
        .into_iter()
        .find(|snapshot| snapshot.player_id == SCENE_VIEW_TIMELINE_PLAYER_ID);
    let mut diagnostics = runtime
        .diagnostics()
        .map(str::to_owned)
        .collect::<Vec<_>>();
    if let Some(error) = control_error {
        diagnostics.push(error);
    }
    TimelinePreviewStatus {
        tick: snapshot.as_ref().map_or(request.tick, |snapshot| snapshot.tick),
        state: snapshot.map_or(requested_state, |snapshot| snapshot.state),
        diagnostics,
    }
}

